- SOURCE_CLAIM_JSON: {"title":"Egypt urged to unblock websites and free journalists as part of national dialogue","publisher":"Reporters Without Borders (RSF)","publication_date":"2022-07-05","url":"https://rsf.org/en/egypt-urged-unblock-websites-and-free-journalists-part-national-dialogue","claim":"RSF said Egypt's national dialogue began with civil society representatives and opposition members, urged the government to unblock websites and free journalists, and noted that 22 journalists were detained at the time.","locator":"Lines 326-332","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Contemporaneous report with specific counts and explicit press-freedom demands.","final_evidence_use":"final_evidence","period_fit":"target-year 2022 reform-and-repression context","ruler_attribution":"Affects the Sisi administration's handling of civil society and media space.","contrary_evidence":["The dialogue itself is consultative and does not prove sustained reform."],"lenses":["4B.3","4B.6","4B.9","4B.10"]}
- SOURCE_CLAIM_JSON: {"title":"Factbox-National political dialogue in Egypt follows years of crackdowns","publisher":"Reuters via Investing.com","publication_date":"2022-07-29","url":"https://www.investing.com/news/world-news/factboxnational-political-dialogue-in-egypt-follows-years-of-crackdowns-2857572","claim":"Reuters reported that the planned national political dialogue was a test of whether authorities would ease a crackdown on dissent, and noted the 2013 protest law requiring prior police approval for demonstrations and tens of thousands detained for political reasons since 2013.","locator":"Lines 418-437 and 471-473","source_type":"media","source_confidence":"medium_high","source_confidence_reason":"Independent wire reporting on a ruler-announced dialogue and the surrounding coercive legal environment.","final_evidence_use":"final_evidence","period_fit":"target-year 2022 political environment and dialogue launch","ruler_attribution":"Directly relevant to Sisi's rule because the dialogue and protest law operated under his presidency.","contrary_evidence":["The government said the crackdown targeted terrorists and saboteurs, not peaceful opponents."],"lenses":["4B.1","4B.3","4B.8","4B.10"]}
