- SOURCE_CLAIM_JSON: {"title":"Egypt: Arrests over calls for protests during COP27 expose reality of human rights crisis","publisher":"Amnesty International","publication_date":"2022-11-06","url":"https://www.amnesty.org/en/latest/news/2022/11/egypt-arrests-over-calls-for-protests-during-cop27-expose-reality-of-human-rights-crisis/","claim":"Amnesty reported hundreds of arrests in connection with calls for peaceful protests during COP27, with at least 151 detainees under investigation and hundreds more questioned.","locator":"Lines 64-73","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Contemporaneous rights reporting with a specific detainee count and clear protest nexus.","final_evidence_use":"final_evidence","period_fit":"target-year 2022 COP27 crackdown","ruler_attribution":"Attributable to Egyptian authorities under Sisi's control.","contrary_evidence":["Authorities also released 766 prisoners over the same period, but Amnesty says arrests outpaced releases and continued to target free speech and association."],"lenses":["4B.3","4B.8","4B.9","4B.10"]}
